using Kerf.Engine.Exchange.Framework;
using Kerf.Engine.Foundation;
using Occt;
using System.Text;
using static Kerf.Engine.Exchange.Framework.ParamType;

namespace Kerf.Engine.Exchange.Step.Parser;

/// <summary>
/// The STEP scanner (OCCT's <c>step::scanner</c>, generated by flex from <c>step.lex</c>), written by hand: it
/// returns the tokens flex's tables return, with the same texts and the same calls into
/// <see cref="ReadData"/> (CreateNewText, SetTypeArg, PrepareNewArg), and counts lines as OCCT does.
/// </summary>
/// <remarks>
/// <para>
/// Flex picks, at each point, the rule matching the longest text, the first in step.lex on a tie (a rule's trailing
/// context counts in its length), and the scanner does the same, rule by rule: the rules' numbers below are flex's
/// (lex.step.cxx's actions). Like OCCT's (<c>%option case-insensitive</c>), it ignores the letters' case.
/// </para>
/// <para>
/// OCCT's scanner keeps a token (with what <c>yymore</c> collected: a quoted string's pieces) in a buffer of 16,384
/// bytes that it can't enlarge (its variable trailing context makes flex's REJECT machinery hold one state per
/// byte), so it fails ("input buffer overflow, can't enlarge buffer because scanner uses REJECT") on a token of
/// 16,384 bytes or more, such as a long string. This scanner's buffer grows as a token needs (Kerf decision 1511),
/// within <see cref="ParserReadLimits.MaxFileSize"/>.
/// </para>
/// <para>
/// Reentrant: each read has its own scanner, parser and data. It reads the stream in blocks.
/// </para>
/// </remarks>
internal sealed class Scanner
{
    // The start conditions (%x Com End Text)
    private const int Initial = 0;
    private const int Com = 1;
    private const int End = 2;
    private const int Text = 3;

    /// <summary>The bytes the buffer holds ahead of a token's start when a token starts, if the input has them.</summary>
    private const int Lookahead = 16383;

    internal readonly ReadData _dataModel;
    private readonly Stream _stream;
    private readonly ParserReadLimits _limits;
    private byte[] _buf = new byte[1 << 18];
    private int _len; // bytes held in myBuf
    private bool _eof; // the stream is at its end (myLen is the input's end)
    private long _read; // bytes read from the stream
    private int _pos; // where the next token starts (yy_c_buf_p)
    private int _textStart; // in Text, where the quoted string started (yymore's text)
    private int _start = Initial; // yy_start
    private int _yylineno = 1;

    /// <summary>A scanner reading <paramref name="stream"/> for <paramref name="dataModel"/>.</summary>
    public Scanner(ReadData dataModel, Stream stream, ParserReadLimits? limits = null)
    {
        _dataModel = dataModel;
        _stream = stream;
        _limits = limits ?? ParserReadLimits.Default;
    }

    /// <summary>The line counter (FlexLexer's lineno(): starts at 1, counts the newlines read).</summary>
    public int Lineno() => _yylineno;

    /// <summary>The limits for hostile input.</summary>
    internal ParserReadLimits Limits => _limits;

    /// <summary>Bytes read from the stream so far.</summary>
    internal long BytesRead => _read;

    /// <summary>The input's length if the stream knows it, else -1.</summary>
    internal long InputLength
    {
        get
        {
            try
            {
                return _stream.CanSeek ? _stream.Length : -1;
            }
            catch (NotSupportedException)
            {
                return -1;
            }
        }
    }

    /// <summary>Raised when the input passes <see cref="ParserReadLimits.MaxFileSize"/>.</summary>
    internal sealed class FileTooLarge : Exception { }

    private void CreateNewText(int theFrom, int to)
    {
        _dataModel.CreateNewText(Encoding.Latin1.GetString(_buf, theFrom, to - theFrom), to - theFrom);
    }

    private void SetTypeArg(ParamType type) => _dataModel.SetTypeArg(type);

    /// <summary>
    /// The next token (<see cref="StepParser.token"/>; 0 at the end of the input), with the scanner's actions
    /// done (OCCT's <c>lex</c>, YY_DECL).
    /// </summary>
    internal int Lex()
    {
        for (;;)
        {
            int p = _pos;
            int tokStart = _start == Text ? _textStart : p;
            if (!_eof && _len - tokStart <= Lookahead)
            {
                Refill(tokStart);
                p = _pos;
                tokStart = _start == Text ? _textStart : p;
            }

            int c = Peek(p);
            switch (_start)
            {
                case Com:
                    if (c < 0)
                    {
                        return 0;
                    }

                    if (c == '\n')
                    {
                        // 12: <*>[\n]
                        _yylineno++;
                        _pos = p + 1;
                    }
                    else if (c == '*')
                    {
                        int i = p + 1;
                        while (Peek(i) == '*')
                        {
                            i++;
                        }

                        if (Peek(i) == '/')
                        {
                            // 4: <Com>[*]+[/], end of comment
                            _pos = i + 1;
                            _start = Initial;
                        }
                        else
                        {
                            // 3: <Com>[*]+[^*/\n]*
                            for (c = Peek(i); c >= 0 && c != '*' && c != '/' && c != '\n'; c = Peek(++i)) { }
                            _pos = i;
                        }
                    }
                    else
                    {
                        // 2: <Com>[^*\n]*
                        int i = p + 1;
                        for (c = Peek(i); c >= 0 && c != '*' && c != '\n'; c = Peek(++i)) { }
                        _pos = i;
                    }

                    continue;

                case End:
                    if (c < 0)
                    {
                        return 0;
                    }

                    if (c == '\n')
                    {
                        _yylineno++;
                        _pos = p + 1;
                    }
                    else
                    {
                        // 43: <End>[^\n], one byte at a time in flex: the run at once here
                        int i = p + 1;
                        while (i < _len && _buf[i] != '\n')
                        {
                            i++;
                        }

                        _pos = i;
                    }

                    continue;

                case Text:
                    if (c < 0)
                    {
                        // The end of the input in a string: flex's yyterminate drops what yymore collected
                        return 0;
                    }

                    if (c == '\n')
                    {
                        // 6: <Text>[\n], yymore
                        _yylineno++;
                        _pos = p + 1;
                    }
                    else if (c == '\'')
                    {
                        // 9: <Text>[']/[" "\n\r]*[\)\,], the end of the string: a quote followed by blanks and ) or ,.
                        // The tab is a blank here too (OCCT's class left it out, so 'a' followed by a tab and a comma
                        // ran on to a later quote; Kerf decision 1512). The class's double quote stays: it only
                        // decides malformed input ('a'"" ends there, as in OCCT).
                        int j = p + 1;
                        int d;
                        for (d = Peek(j); d is ' ' or '\t' or '"' or '\n' or '\r'; d = Peek(++j)) { }
                        _pos = p + 1;
                        if (d == ')' || d == ',')
                        {
                            _start = Initial;
                            CreateNewText(_textStart, p + 1);
                            SetTypeArg(ParamType.ParamText);
                            return StepParser.token.QUID;
                        }

                        // 7: <Text>['], yymore
                    }
                    else
                    {
                        // 8: <Text>[^\n']+, yymore
                        int i = p + 1;
                        for (c = Peek(i); c >= 0 && c != '\n' && c != '\''; c = Peek(++i)) { }
                        _pos = i;
                    }

                    continue;
            }

            // INITIAL
            switch (c)
            {
                case < 0:
                    return 0;
                case '\n':
                    // 12: <*>[\n]
                    _yylineno++;
                    _pos = p + 1;
                    continue;
                case ' ':
                case '\t':
                case '\r':
                    // 10, 11, 13 (abv 30.06.00: for reading DOS files)
                    _pos = p + 1;
                    continue;
                case 0:
                {
                    // 14: [\0]+ (fix from C21. for test load e3i file with line 15 with null symbols)
                    int i = p + 1;
                    while (Peek(i) == 0)
                    {
                        i++;
                    }

                    _pos = i;
                    continue;
                }
                case '/':
                    if (Peek(p + 1) == '*')
                    {
                        // 1: "/*", start of comment
                        _start = Com;
                        _pos = p + 2;
                        continue;
                    }

                    // 37: [/]
                    _pos = p + 1;
                    return '/';
                case '\'':
                    // 5: ['], start of quoted text string, kept as part of the text (yymore)
                    _start = Text;
                    _textStart = p;
                    _pos = p + 1;
                    continue;
                case '(':
                    _pos = p + 1;
                    return '(';
                case ')':
                    _pos = p + 1;
                    return ')';
                case ',':
                    _pos = p + 1;
                    _dataModel.PrepareNewArg();
                    return ',';
                case '$':
                    _pos = p + 1;
                    CreateNewText(p, p + 1);
                    SetTypeArg(ParamType.ParamVoid);
                    return StepParser.token.QUID;
                case '=':
                    _pos = p + 1;
                    return '=';
                case ';':
                    _pos = p + 1;
                    return ';';
                case '#':
                {
                    int i = p + 1;
                    while (IsDigit(Peek(i)))
                    {
                        i++;
                    }

                    if (i == p + 1)
                    {
                        return Misc(p);
                    }

                    // 15: #[0-9]+/=, 16: #[0-9]+/[ \t]*= (the entity's label), 17: #[0-9]+ (a reference)
                    int j = i;
                    int d;
                    for (d = Peek(j); d == ' ' || d == '\t'; d = Peek(++j)) { }
                    _pos = i;
                    CreateNewText(p, i);
                    return d == '=' ? StepParser.token.ENTITY : StepParser.token.IDENT;
                }
                case '"':
                {
                    // 21: ["][0-9A-F]+["]
                    int i = p + 1;
                    while (IsHex(Peek(i)))
                    {
                        i++;
                    }

                    if (i == p + 1 || Peek(i) != '"')
                    {
                        return Misc(p);
                    }

                    _pos = i + 1;
                    CreateNewText(p, i + 1);
                    SetTypeArg(ParamType.ParamHexa);
                    return StepParser.token.QUID;
                }
                case '&':
                {
                    // 38: &(?i:SCOPE)
                    if (MatchWord(p + 1, "SCOPE") == p + 6)
                    {
                        _pos = p + 6;
                        return StepParser.token.SCOPE;
                    }

                    return Misc(p);
                }
                case '!':
                {
                    // 41: ![a-zA-Z0-9_]+
                    int i = p + 1;
                    while (IsWord(Peek(i)))
                    {
                        i++;
                    }

                    if (i == p + 1)
                    {
                        return Misc(p);
                    }

                    _pos = i;
                    CreateNewText(p, i);
                    return StepParser.token.TYPE;
                }
            }

            if (c == '-' || c == '+' || c == '.' || IsWord(c))
            {
                return Word(p, c);
            }

            return Misc(p);
        }
    }

    /// <summary>42: [^)], any other byte: a parameter of unknown kind.</summary>
    private int Misc(int p)
    {
        _pos = p + 1;
        CreateNewText(p, p + 1);
        SetTypeArg(ParamType.ParamMisc);
        return StepParser.token.QUID;
    }

    /// <summary>
    /// The rules starting with a sign, a dot, a digit, a letter or an underscore: the numbers (18 to 20), the
    /// enumerations (22), the keywords (29 to 36, 39) and the names (40), the longest match winning, then the first.
    /// </summary>
    private int Word(int p, int c)
    {
        // 42 ([^)], one byte) unless a rule matches (a tie goes to the other rule, which comes first)
        int best = 42;
        int aLen = 0;

        void Take(int rule, int len)
        {
            if (len > aLen)
            {
                best = rule;
                aLen = len;
            }
        }

        bool isDigit = IsDigit(c);
        // 18: [-+0-9][0-9]*
        if (isDigit || c == '-' || c == '+')
        {
            int i = p + 1;
            while (IsDigit(Peek(i)))
            {
                i++;
            }

            Take(18, i - p);
        }

        // 19: [-+\.0-9][\.0-9]+, 20: [-+\.0-9][\.0-9]+E[-+0-9][0-9]*
        if (isDigit || c == '-' || c == '+' || c == '.')
        {
            int j = p + 1;
            int d;
            for (d = Peek(j); IsDigit(d) || d == '.'; d = Peek(++j)) { }
            if (j > p + 1)
            {
                Take(19, j - p);
                if ((d == 'E' || d == 'e') && (IsDigit(d = Peek(j + 1)) || d == '-' || d == '+'))
                {
                    int k = j + 2;
                    while (IsDigit(Peek(k)))
                    {
                        k++;
                    }

                    Take(20, k - p);
                }
            }
        }

        // 22: [.]*[A-Z0-9_]+[.]
        if (c == '.' || IsWord(c))
        {
            int a = p;
            while (Peek(a) == '.')
            {
                a++;
            }

            int b = a;
            while (IsWord(Peek(b)))
            {
                b++;
            }

            if (b > a && Peek(b) == '.')
            {
                Take(22, b + 1 - p);
            }
        }

        if (IsLetter(c))
        {
            // The keywords
            int k;
            switch (c | 0x20)
            {
                case 's':
                    // 29: (?i:STEP);
                    if (MatchWord(p, "STEP;") == p + 5)
                    {
                        Take(29, 5);
                    }

                    break;
                case 'h':
                    // 30: (?i:HEADER);
                    if (MatchWord(p, "HEADER;") == p + 7)
                    {
                        Take(30, 7);
                    }

                    break;
                case 'd':
                    // 32: (?i:DATA);
                    if (MatchWord(p, "DATA;") == p + 5)
                    {
                        Take(32, 5);
                    }

                    break;
                case 'e':
                    k = MatchWord(p, "END");
                    if (k == p + 3)
                    {
                        int d = Peek(k);
                        if ((d | 0x20) == 's')
                        {
                            // 31: (?i:ENDSEC); 33: (?i:ENDSTEP); 34: (?i:ENDSTEP);.* 39: (?i:ENDSCOPE)
                            if (MatchWord(p, "ENDSEC;") == p + 7)
                            {
                                Take(31, 7);
                            }
                            else if (MatchWord(p, "ENDSCOPE") == p + 8)
                            {
                                Take(39, 8);
                            }
                            else if (MatchWord(p, "ENDSTEP;") == p + 8)
                            {
                                Take(33, 8);
                                int i = p + 8;
                                for (d = Peek(i); d >= 0 && d != '\n'; d = Peek(++i)) { }
                                Take(34, i - p);
                            }
                        }
                        else if (d == '-')
                        {
                            // 35: (?i:END-ISO)[0-9\-]*;
                            k = MatchWord(p, "END-ISO");
                            if (k == p + 7)
                            {
                                while (IsDigit(d = Peek(k)) || d == '-')
                                {
                                    k++;
                                }

                                if (d == ';')
                                {
                                    Take(35, k + 1 - p);
                                }
                            }
                        }
                    }

                    break;
                case 'i':
                    // 36: (?i:ISO)[0-9\-]*;
                    k = MatchWord(p, "ISO");
                    if (k == p + 3)
                    {
                        int d;
                        while (IsDigit(d = Peek(k)) || d == '-')
                        {
                            k++;
                        }

                        if (d == ';')
                        {
                            Take(36, k + 1 - p);
                        }
                    }

                    break;
            }
        }

        // 40: [a-zA-Z0-9_]+
        if (IsWord(c))
        {
            int i = p + 1;
            while (IsWord(Peek(i)))
            {
                i++;
            }

            Take(40, i - p);
        }

        _pos = p + aLen;
        switch (best)
        {
            case 18:
                CreateNewText(p, p + aLen);
                SetTypeArg(ParamType.ParamInteger);
                return StepParser.token.QUID;
            case 19:
            case 20:
                CreateNewText(p, p + aLen);
                SetTypeArg(ParamType.ParamReal);
                return StepParser.token.QUID;
            case 22:
                CreateNewText(p, p + aLen);
                SetTypeArg(ParamType.ParamEnum);
                return StepParser.token.QUID;
            case 29:
            case 36:
                return StepParser.token.STEP;
            case 30:
                return StepParser.token.HEADER;
            case 31:
                return StepParser.token.ENDSEC;
            case 32:
                return StepParser.token.DATA;
            case 33:
            case 34:
                return StepParser.token.ENDSTEP;
            case 35:
                // at the end of the STEP data, the dedicated start condition End skips everything that follows
                _start = End;
                return StepParser.token.ENDSTEP;
            case 39:
                return StepParser.token.ENDSCOPE;
            case 40:
                CreateNewText(p, p + aLen);
                return StepParser.token.TYPE;
            default:
                return Misc(p);
        }
    }

    /// <summary>The byte at <paramref name="i"/>, -1 at the end of the input; the buffer grows as a token needs.</summary>
    private int Peek(int i)
    {
        while (i >= _len && !_eof)
        {
            ReadMore();
        }

        return i < _len ? _buf[i] : -1;
    }

    /// <summary>Reads more of the stream after the buffer's bytes, the buffer doubled when it is full.</summary>
    private void ReadMore()
    {
        if (_len == _buf.Length)
        {
            if (_buf.Length > Array.MaxLength / 2)
            {
                throw new FileTooLarge();
            }
            Array.Resize(ref _buf, _buf.Length * 2);
        }

        int read = _stream.Read(_buf, _len, _buf.Length - _len);
        if (read <= 0)
        {
            _eof = true;
            return;
        }

        _len += read;
        _read += read;
        if (_read > _limits.MaxFileSize)
        {
            throw new FileTooLarge();
        }
    }

    /// <summary>Where the case-insensitive match of <paramref name="word"/> at <paramref name="p"/> stops.</summary>
    private int MatchWord(int p, string word)
    {
        for (int i = 0; i < word.Length; i++)
        {
            int c = Peek(p + i);
            char w = word[i];
            if (c != w && !(w is >= 'A' and <= 'Z' && c == (w | 0x20)))
            {
                return p + i;
            }
        }

        return p + word.Length;
    }

    private static bool IsDigit(int c) => (uint)(c - '0') <= 9;

    private static bool IsLetter(int c) => (uint)((c | 0x20) - 'a') <= 'z' - 'a';

    private static bool IsWord(int c) => IsDigit(c) || IsLetter(c) || c == '_';

    private static bool IsHex(int c) => IsDigit(c) || (uint)((c | 0x20) - 'a') <= 'f' - 'a';

    /// <summary>
    /// Moves the current token to the buffer's start and reads, so that the buffer is full, or holds the input's end.
    /// </summary>
    private void Refill(int tokStart)
    {
        if (tokStart > 0)
        {
            Buffer.BlockCopy(_buf, tokStart, _buf, 0, _len - tokStart);
            _len -= tokStart;
            _pos -= tokStart;
            _textStart -= tokStart;
        }

        while (_len < _buf.Length)
        {
            int read = _stream.Read(_buf, _len, _buf.Length - _len);
            if (read <= 0)
            {
                _eof = true;
                break;
            }

            _len += read;
            _read += read;
            if (_read > _limits.MaxFileSize)
            {
                throw new FileTooLarge();
            }
        }
    }
}
